    folderStable: true,
    folderStableWaitedMs: summary.waitedMs,
    folderStableChecks: summary.checks,
    folderStableImageCount: summary.count,
    folderStableTotalBytes: summary.totalBytes,
    folderStableFiles: summary.files,
  },
}];

const parsed = $('Parse Product Folder').first()?.json || {};
const lookup = $input.first()?.json || {};
const defaultDownloadFatherFolder = "G:\\01_MerchRoute\\02_GenerateFolder\\E001-抠图-下载";

function cleanString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

if (lookup.success !== true || !lookup.data || typeof lookup.data !== 'object' || Array.isArray(lookup.data)) {
  throw new Error('读取 n8n_setParameter 配置失败：' + String(lookup.message || lookup.errorType || 'S016 data is missing'));
}

const data = lookup.data;
const configFile = lookup.latestFile?.filePath || lookup.latestFile?.fileName || 'n8n_setParameter_xxx.json';
const SKU = cleanString(data.SKU);
const productName = cleanString(data.productName);
if (!/^\d{7}$/.test(SKU)) throw new Error(configFile + ' 的 SKU 必须是保留前导零的 7 位数字。');
if (!productName) throw new Error(configFile + ' 的 productName 不能为空。');

const downloadFatherFolder = cleanString(data.downloadFatherFolder) || defaultDownloadFatherFolder;
return [{ json: { ...parsed, SKU, productName, downloadFatherFolder } }];

const config = $('setParameter').first().json || {};
const tasks = Array.isArray(config.imageTasks) ? config.imageTasks : [];
const uploadedItems = $input.all();

function cleanString(value) {
  return String(value ?? '').trim();
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(cleanString(value));
}

if (tasks.length < 1) {
  throw new Error('setParameter.imageTasks must contain at least one task.');
}

if (uploadedItems.length !== tasks.length) {
  throw new Error('SiliconFlow upload count mismatch: expected ' + tasks.length + ', received ' + uploadedItems.length);
}

const uploadedByIndex = new Map();
for (const [position, item] of uploadedItems.entries()) {
  const row = item.json || {};
  const inputIndex = Number(row.inputIndex);
  const sourceFileName = cleanString(row.sourceFileName);
  const url = cleanString(row.url);

  if (!Number.isInteger(inputIndex) || inputIndex < 0 || inputIndex >= tasks.length) {
    throw new Error('Invalid SiliconFlow inputIndex at result ' + (position + 1) + ': ' + row.inputIndex);
  }
  if (uploadedByIndex.has(inputIndex)) {
    throw new Error('Duplicate SiliconFlow inputIndex: ' + inputIndex);
  }
  const expectedFileName = cleanString(tasks[inputIndex]?.sourceFileName);
  if (!sourceFileName || sourceFileName !== expectedFileName) {
    throw new Error('SiliconFlow filename mismatch at inputIndex ' + inputIndex + ': expected ' + expectedFileName + ', received ' + (sourceFileName || '(empty)'));
  }
  if (!isHttpUrl(url)) {
    throw new Error('SiliconFlow URL is missing or invalid for ' + expectedFileName);
  }
  uploadedByIndex.set(inputIndex, url);
}

const imageTasks = tasks.map((task, index) => {
  const imageUrl = uploadedByIndex.get(index);
  if (!imageUrl) throw new Error('Missing SiliconFlow URL for task ' + (task.taskId || index + 1));
  return { ...task, imageUrl };
});

return [{
  json: {
    ...config,
    imageTasks,
  },
}];
